const out = [];
for (const item of $input.all()) {
  for (const c of (item.json.data || [])) {
    const prices = c.tcgplayer?.prices;
    if (!prices) continue;
    for (const [variant, p] of Object.entries(prices)) {
      const m = Number(p?.market);
      if (!m || m <= 0) continue;
      out.push({ json: {
        card_id: c.id,
        variant,
        name: c.name,
        set_name: c.set?.name ?? '',
        number: c.number ?? '',
        rarity: c.rarity ?? '',
        image_small: c.images?.small ?? '',
        image_large: c.images?.large ?? '',
        market: m,
        tcg_updated: c.tcgplayer?.updatedAt ?? '',
      }});
    }
  }
}
return out;

const cfg = $('Config Movers').first().json;
const rows0 = $input.all().map(i => i.json);
if (!rows0.length) {
  throw new Error('No comparable snapshots yet. Need two nightly snapshots at least windowDays apart.');
}

// De-duplicate (the two SQL halves can overlap when data is small)
const seen = new Map();
for (const r of rows0) {
  seen.set(r.card_id + '|' + r.variant, {
    ...r,
    pct: Number(r.pct),
    old_price: Number(r.old_price),
    new_price: Number(r.new_price),
  });
}
const rows = [...seen.values()];
const gain = rows.filter(r => r.pct > 0).sort((a, b) => b.pct - a.pct).slice(0, 5);
const fall = rows.filter(r => r.pct < 0).sort((a, b) => a.pct - b.pct).slice(0, 3);
if (!gain.length) throw new Error('No gainers found for this window.');

const curDate = rows[0].cur_date;
const baseDate = rows[0].base_date;
const days = Math.max(1, Math.round((new Date(curDate) - new Date(baseDate)) / 86400000));
const windowLabel = days === 1 ? 'LAST 24 HOURS' : 'LAST ' + days + ' DAYS';

const esc = s => String(s ?? '').replace(/[&<>\"]/g, c => ({ '&': '&', '<': '<', '>': '>', '"': '"' }[c]));
const money = n => '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const pctFmt = p => (p > 0 ? '+' : '') + p.toFixed(1) + '%';
const vLabel = v => String(v).replace(/([A-Z])/g, ' $1').replace(/^./, c => c.toUpperCase());
const img = (src, h) => src ? '<img src="' + esc(src) + '" style="height:' + h + 'px">' : '';

const hero = gain[0];
const rest = gain.slice(1);

const heroHtml = `
<div class="hero">
  ${img(hero.image_large, 464)}
  <div class="info">
    <div class="tag">#1 BIGGEST GAINER</div>
    <div class="hname">${esc(hero.name)}</div>
    <div class="meta">${esc(hero.set_name)} · #${esc(hero.number)} · ${esc(vLabel(hero.variant))}</div>
    <div class="big">${pctFmt(hero.pct)}</div>
    <div class="prices">${money(hero.old_price)} → <b>${money(hero.new_price)}</b></div>
  </div>
</div>`;

const rowsHtml = rest.map((r, i) => `
<div class="row">
  <div class="rank">${i + 2}</div>
  ${img(r.image_small, 70)}
  <div class="rname"><div class="n">${esc(r.name)}</div><div class="s">${esc(r.set_name)} · ${esc(vLabel(r.variant))}</div></div>
  <div class="rp">${money(r.old_price)} → ${money(r.new_price)}</div>
  <div class="rpct up">${pctFmt(r.pct)}</div>
</div>`).join('');

const fallHtml = fall.length ? `
<div class="sec">BIGGEST DROPS</div>
<div class="fall">${fall.map(r => `
  <div class="fc">
    ${img(r.image_small, 128)}
    <div class="fi">
      <div class="n">${esc(r.name)}</div>
      <div class="s">${esc(r.set_name)}</div>
      <div class="fp">${pctFmt(r.pct)}</div>
      <div class="s">${money(r.old_price)} → ${money(r.new_price)}</div>
    </div>
  </div>`).join('')}
</div>` : '';

const html = `<!doctype html><html><head><meta charset="utf-8"><style>
* { box-sizing: border-box; margin: 0; padding: 0 }
body { width: 1080px; height: 1350px; overflow: hidden; font-family: 'DejaVu Sans', 'Liberation Sans', Arial, sans-serif; color: #fff; background: radial-gradient(circle at 20% 0%, #1d2f6b 0, #0b1230 55%, #070b1d 100%); display: flex; flex-direction: column; padding: 44px 52px }
.head { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 26px }
.title { font-size: 80px; font-weight: 900; letter-spacing: 2px; color: #ffd23f; line-height: 1 }
.sub { font-size: 27px; color: #9fb0e6; text-align: right; line-height: 1.35 }
.hero { display: flex; gap: 36px; background: rgba(255, 255, 255, .06); border: 2px solid rgba(255, 210, 63, .35); border-radius: 28px; padding: 28px; height: 520px }
.hero img { border-radius: 14px; box-shadow: 0 0 60px rgba(255, 210, 63, .35) }
.info { display: flex; flex-direction: column; justify-content: center; flex: 1 }
.tag { font-size: 23px; color: #ffd23f; letter-spacing: 3px; font-weight: 700 }
.hname { font-size: 50px; font-weight: 800; margin: 10px 0 6px; line-height: 1.05 }
.meta { font-size: 25px; color: #9fb0e6; margin-bottom: 20px }
.big { font-size: 116px; font-weight: 900; color: #3ddc84; line-height: 1 }
.prices { font-size: 34px; margin-top: 14px; color: #dfe6ff }
.sec { font-size: 24px; letter-spacing: 3px; color: #9fb0e6; font-weight: 700; margin: 22px 0 8px }
.row { display: flex; align-items: center; gap: 18px; height: 86px; border-bottom: 1px solid rgba(255, 255, 255, .1) }
.row img { border-radius: 6px }
.rank { width: 40px; font-size: 34px; font-weight: 900; color: #ffd23f; text-align: center }
.rname { flex: 1; min-width: 0 }
.n { font-size: 28px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis }
.s { font-size: 20px; color: #9fb0e6; white-space: nowrap; overflow: hidden; text-overflow: ellipsis }
.rp { font-size: 24px; color: #dfe6ff }
.rpct { font-size: 36px; font-weight: 900; width: 170px; text-align: right }
.up { color: #3ddc84 }
.fall { display: flex; gap: 16px }
.fc { flex: 1; min-width: 0; display: flex; gap: 14px; align-items: center; background: rgba(255, 90, 90, .08); border: 2px solid rgba(255, 90, 90, .3); border-radius: 18px; padding: 12px }
.fc img { border-radius: 6px }
.fi { min-width: 0; flex: 1 }
.fp { font-size: 36px; font-weight: 900; color: #ff5c5c }
.foot { margin-top: auto; font-size: 18px; color: #6f7fb3; line-height: 1.35 }
</style></head><body>
<div class="head">
  <div class="title">TOP MOVERS</div>
  <div class="sub">${windowLabel}<br>${esc(curDate)} · Pokémon cards</div>
</div>
${heroHtml}
<div class="sec">MORE GAINERS</div>
${rowsHtml}
${fallHtml}
<div class="foot">Prices are TCGplayer market estimates via pokemontcg.io, compared ${esc(baseDate)} to ${esc(curDate)}. Not financial advice. Not affiliated with Nintendo or The Pokémon Company.</div>
</body></html>`;

const fileName = 'top-movers_' + curDate + '_' + days + 'd.png';
const bin = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
return [{ json: { fileName, outputDir: cfg.outputDir, gotenbergUrl: cfg.gotenbergUrl }, binary: { data: bin } }];
